{"exp_id": "w5_lora_scierc_constrained_eval", "conclusion": "success", "hypothesis": "Fine-tuning + constrained decoding composability: 约束解码在 fine-tuned 模型上仍有效，且不显著损害 F1", "parent": null, "hyp_len": 83}
{"exp_id": "w5_lora_scierc_training", "conclusion": "success", "hypothesis": null, "parent": null, "hyp_len": 0}
{"exp_id": "w5_lora_scierc_unconstrained_eval", "conclusion": "success", "hypothesis": "Fine-tuned Qwen3-8B still produces >2% decode rate violations on SciERC unconstrained, justifying OntoCoDec constraint application", "parent": "w5_lora_scierc_training", "hyp_len": 130}
{"exp_id": "w5_qwen_docred_lora_constrained_eval", "conclusion": "success", "hypothesis": "Fine-tuned Qwen3-8B DocRED LoRA + OntoCoDec constrained eval — 验证 composability：约束解码在 fine-tuned Qwen DocRED 上是否仍能消除残余 DR 且不损 R-F1", "parent": "w5_qwen_docred_lora_training", "hyp_len": 130}
